  levels,tuning,settled,sl=F._harmonic_features(x,rate,onset,e['midi']);early=F._pitch_trajectory_features(x,rate,onset,settled,sl)
  rows[e['id']]={**e,'sha256':sha(path),'first_nonzero_sample':int(nz[0]) if nz.size else None,'stroke_onset_sample':stroke,'fit_onset_sample':onset,'velocity_balance_db':balance(x,rate,e['midi'],stroke),'settled_pitch_cents_median_H1_H4':np.nanmedian(tuning[:4]),'H1_pitch_cents':tuning[0],'early_relative_pitch_cents':early.tolist()}
 return rows
