// Offline friend diagnostic: released delay-line state before any feedback.
#include "DSP/AcustraEngine.h"
#include <algorithm>
#include <array>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <memory>
#include <stdexcept>
namespace acustra {
struct AcustraEngineTestAccess {
 static void write(const AcustraEngine& engine,int channel,std::ostream& out) {
  const auto& v=engine.voices_[static_cast<std::size_t>(channel-1)];
  if(!v.played || !v.attackFired)throw std::runtime_error("probe did not fire its explicit attack");
  out<<",\"fret\":"<<v.fret<<",\"open_midi\":"<<v.openMidi<<",\"pluck_point\":"<<v.pluckPoint<<",\"contact_period_samples\":"<<v.contactPeriodSamples<<",\"attack_slope_energy\":"<<v.attackSlopeEnergy<<",\"slip_pole\":"<<v.releaseSlipPole<<",\"reference_pole\":"<<v.releaseReferencePole<<",\"planes\":[";
  for(int plane=0;plane<2;++plane) {
   if(plane)out<<',';
   const auto& loop=v.loops[static_cast<std::size_t>(plane)];
   const int n=std::clamp(static_cast<int>(std::round(loop.currentDelay)),8,AcustraEngine::maximumDelaySamples-3);
