namespace acustra {
struct AcustraEngineTestAccess {
 static void scales(float f,float q){offlineT1FrequencyScale=f;offlineT1QScale=q;}
 static bool ports(const AcustraEngine&e){return e.bridgeCouplingEnabled_&&e.sympatheticStringsEnabled_&&std::all_of(e.voices_.begin(),e.voices_.end(),[](const auto&v){return v.characteristicImpedance>0;});}
 static std::vector<float> residues(const AcustraEngine&e){
  std::vector<float>v;const auto&b=e.bridgeLoad_;
  for(int i=0;i<e.bridgeModeCount;++i){v.push_back(b.residueHeave[i]);v.push_back(b.residueCross[i]);v.push_back(b.residueRock[i]);}
  return v;
 }
 static void verify(const AcustraEngine&e,std::ostream&o){
  const auto&t=e.bridgeMobilityTable();o<<'[';
  for(int body:{1,134}){
   const auto&b=e.bodyBank_;double f=std::atan2(b.poleImaginary[body],b.poleReal[body])*48000/(2*piDouble);
   double r=std::hypot(double(b.poleReal[body]),double(b.poleImaginary[body]));double t60=-std::log(1000.0)/(48000*std::log(r));
   int nearest=0;double diff=1e9,bridgeHz=0,bridgeQ=0;
   for(int i=0;i<t.count;++i){double hz=std::atan(t.modes[i].omega/(2*48000.0))*48000/piDouble;if(std::abs(hz-f)<diff){diff=std::abs(hz-f);nearest=i;bridgeHz=hz;bridgeQ=t.modes[i].omega/(2*t.modes[i].damping);}}
   double bodyQ=f*t60*piDouble/std::log(1000.0);
   // Inverting a stored float radius amplifies ~1ulp coefficient error at highQ.
   // Verify the actual complex pole coefficients against the bridge analog pole
   // as well as a relative Q roundoff bound; never loosen frequency agreement.
   const auto expected=std::polar(std::exp(-pi*float(bridgeHz)/(float(bridgeQ)*48000.f)),twoPi*float(bridgeHz)/48000.f);
   const double poleError=std::max(std::abs(double(expected.real())-b.poleReal[body]),std::abs(double(expected.imag())-b.poleImaginary[body]));
   if(diff>3e-5||std::abs(bodyQ-bridgeQ)>8e-4*bridgeQ||poleError>1.2e-7){std::ostringstream error;error<<"runtime bridge/body pole mismatch index="<<body<<" body_f="<<f<<" bridge_f="<<bridgeHz<<" body_q="<<bodyQ<<" bridge_q="<<bridgeQ;throw std::runtime_error(error.str());}
   if(body==134)o<<',';
   o<<"{\"body_index\":"<<body<<",\"frequency\":"<<f<<",\"t60\":"<<t60<<",\"q\":"<<bodyQ<<",\"bridge_index\":"<<nearest<<",\"bridge_frequency\":"<<bridgeHz<<",\"bridge_q\":"<<bridgeQ<<",\"body_pole_coefficient_error\":"<<poleError<<'}';
  }o<<']';
 }
 static float quarter(const AcustraEngine&e,int i){return e.voices_[i].loops[0].displacementAt(.25f);}
 static void loops(const AcustraEngine&e,std::ostream&o){o<<'[';for(int i=0;i<6;++i){const auto&v=e.voices_[i];if(i)o<<',';o<<"{\"string\":"<<i<<",\"played\":"<<(v.played?"true":"false")<<",\"midi\":"<<v.midiNote<<",\"normal_delay\":"<<v.loops[0].currentDelay<<",\"parallel_delay\":"<<v.loops[1].currentDelay<<",\"loop_gain\":"<<v.loops[0].loopGain<<",\"impedance\":"<<v.characteristicImpedance<<'}';}o<<']';}
};}
int main(int argc,char**argv){try{
 if(argc!=3)throw std::runtime_error("usage: PoleBracket OUTDIR SAVED_BASELINE_DIR");
 const std::filesystem::path out(argv[1]),saved(argv[2]);if(std::filesystem::exists(out)&&!std::filesystem::is_empty(out))throw std::runtime_error("output must be empty");std::filesystem::create_directories(out);
 using A=acustra::AcustraEngineTestAccess;
 std::ofstream report(out/"manifest.json");report<<std::setprecision(10)<<"{\"schema\":1,\"controls\":\"Original,Dreadnought,Spruce,Steel,dryStereoMic,velocity91,defaults\",\"work_guard\":\"Stationary supplied-work ledger only; not complete string/hand/body energy proof\",\"captures\":[";int row=0;
 // Baseline first: refuse to advance if copied-source whole audio differs.
 std::vector<std::pair<float,float>>grid{{1,1}};for(float f:{.96f,1.f,1.04f})for(float q:{.5f,1.f,2.f,4.f})if(f!=1||q!=1)grid.emplace_back(f,q);
 std::vector<float>baseResidues;
 for(auto[factor,qfactor]:grid)for(auto picking:{acustra::PickingTechnique::Finger,acustra::PickingTechnique::Pick})for(int midi:{64,67,72}){
  A::scales(factor,qfactor);auto e=std::make_unique<acustra::AcustraEngine>();acustra::EngineParameters p;p.room=0;p.picking=picking;e->setParameters(p);e->prepare(48000,1);
  auto residues=A::residues(*e);if(baseResidues.empty())baseResidues=residues;if(residues!=baseResidues)throw std::runtime_error("bridge residue matrices changed");
  if(!A::ports(*e))throw std::runtime_error("six ports required");std::ostringstream poles; poles<<std::setprecision(10);A::verify(*e,poles);
  e->noteOn(midi,91.f/127.f);std::vector<float>audio,trace;audio.reserve(144000);trace.reserve(72000*6);std::array<double,3>work{},minimum{},maximum{};float peak=0;
  for(int n=0;n<72000;++n){float l,r;e->process(&l,&r,1);if(!std::isfinite(l)||!std::isfinite(r))throw std::runtime_error("nonfinite audio");audio.insert(audio.end(),{l,r});peak=std::max({peak,std::abs(l),std::abs(r)});for(int i=0;i<6;++i){float v=A::quarter(*e,i);if(!std::isfinite(v))throw std::runtime_error("nonfinite string trace");trace.push_back(v);}
   std::array<float,3> powers{e->getLastBridgePower(),e->getLastBridgeBodyPower(),e->getLastBridgeTailPower()};for(int i=0;i<3;++i){work[i]+=powers[i]/48000.;minimum[i]=std::min(minimum[i],work[i]);maximum[i]=std::max(maximum[i],work[i]);}}
  if(!A::ports(*e)||A::residues(*e)!=baseResidues)throw std::runtime_error("postcapture invariants failed");
  for(int i=0;i<3;++i)if(!std::isfinite(work[i])||minimum[i]<(i==2?-1e-4*maximum[i]-1e-15:-1e-14))throw std::runtime_error("stationary bridge supplied-work guard failed");
  if(!(peak>0&&peak<.89125094))throw std::runtime_error("headroom/finite guard failed");
  std::string technique=picking==acustra::PickingTechnique::Finger?"finger":"pick";
  if(factor==1&&qfactor==1){auto path=saved/(technique+"-"+std::to_string(midi)+"-baseline.audio.f32");std::ifstream file(path,std::ios::binary);std::vector<float>baseline(audio.size());file.read(reinterpret_cast<char*>(baseline.data()),baseline.size()*sizeof(float));if(!file||std::memcmp(audio.data(),baseline.data(),audio.size()*sizeof(float)))throw std::runtime_error("copied-source baseline audio not bit identical");}
  std::ostringstream key;key<<technique<<'-'<<midi<<"-f"<<factor<<"-q"<<qfactor;std::string a=key.str()+".audio.f32",t=key.str()+".string.f32";
  std::ofstream af(out/a,std::ios::binary),tf(out/t,std::ios::binary);af.write(reinterpret_cast<char*>(audio.data()),audio.size()*sizeof(float));tf.write(reinterpret_cast<char*>(trace.data()),trace.size()*sizeof(float));if(!af||!tf)throw std::runtime_error("write failed");
  if(row++)report<<',';report<<"{\"key\":\""<<key.str()<<"\",\"picking\":\""<<technique<<"\",\"midi\":"<<midi<<",\"frequency_factor\":"<<factor<<",\"q_factor\":"<<qfactor<<",\"audio\":\""<<a<<"\",\"string_trace\":\""<<t<<"\",\"sample_rate\":48000,\"frames\":72000,\"reciprocal_ports\":6,\"peak\":"<<peak<<",\"bridge_residue_matrices_bit_identical\":true,\"poles\":"<<poles.str()<<",\"minimum_work\":["<<minimum[0]<<','<<minimum[1]<<','<<minimum[2]<<"],\"loops_after_capture\":";A::loops(*e,report);report<<'}';
 }report<<"]}\n";std::cout<<row<<" captures; baseline wholeaudio byte parity, matching bridge/body poles, matrices/sixports/finite/stationarywork checked\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}

