  for (auto [index,gain] : {std::pair{1,main},std::pair{134,joint}}) {
   auto& b=e.bodyBank_;
   for(auto* a:{&b.leftReal,&b.leftImaginary,&b.rightReal,&b.rightImaginary,
               &b.leftMomentReal,&b.leftMomentImaginary,&b.rightMomentReal,&b.rightMomentImaginary})
    (*a)[index] *= gain;
  }
 }
 static void observe(const AcustraEngine& e,std::uint64_t& hash) {
  auto add=[&](float value){hash^=std::bit_cast<std::uint32_t>(value);hash*=1099511628211ULL;};
  add(e.lastBridgeBodyForce_);add(e.lastBridgeVelocity_);
  for(const auto& voice:e.voices_) {
   add(voice.loops[0].displacementAt(.25f));add(voice.loops[1].displacementAt(.25f));
  }
 }
};
}
