 static void validate(const AcustraEngine&e,std::ostream&o){o<<'[';
  for(int body:{1,134}){
   const auto&b=e.bodyBank_;double f=std::atan2(b.poleImaginary[body],b.poleReal[body])*48000/(2*piDouble);
   double best=1e9,actualHz=0,actualQ=0;int index=-1;
   // Inverse bilinear transform of actual stored denominator roots, not the
   // companion mobility table. Both heave/rock carry the same pole pair.
   for(int i=0;i<e.bridgeModeCount;++i){const auto&m=e.bridgeLoad_.heaveModes[i];
    if(!(m.denominator2>0&&m.denominator1*m.denominator1<4*m.denominator2))continue;
    const std::complex<double>z(-m.denominator1/2,std::sqrt(m.denominator2-m.denominator1*m.denominator1/4));
    const auto s=96000.0*(z-1.0)/(z+1.0);double omega=std::abs(s),hz=std::atan(omega/96000.0)*48000/piDouble,q=omega/(-2*s.real());
    if(std::abs(hz-f)<best){best=std::abs(hz-f);actualHz=hz;actualQ=q;index=i;}}
   if(best>5e-5||index<0)throw std::runtime_error("actual bridge denominator frequency mismatches body");
   const auto&m=e.bridgeLoad_.heaveModes[index];const auto&r=e.bridgeLoad_.rockModes[index];
   if(m.denominator1!=r.denominator1||m.denominator2!=r.denominator2)throw std::runtime_error("heave/rock denominator mismatch");
   const auto expected=std::polar(std::exp(-pi*float(actualHz)/(float(actualQ)*48000.f)),twoPi*float(actualHz)/48000.f);
   double error=std::max(std::abs(double(expected.real())-b.poleReal[body]),std::abs(double(expected.imag())-b.poleImaginary[body]));
   if(error>1.2e-7)throw std::runtime_error("actual bridge denominator damping mismatches body");
   if(body==134)o<<',';o<<"{\"body_index\":"<<body<<",\"body_frequency\":"<<f<<",\"bridge_slot\":"<<index<<",\"actual_bridge_frequency\":"<<actualHz<<",\"actual_bridge_q\":"<<actualQ<<",\"body_pole_coefficient_error\":"<<error<<'}';
  }o<<']';
 }
};}
