#!/usr/bin/env python3
"""Frozen Q1/Q4 full-corpus diagnostic; no production changes or promotion.

Q1 must match every cached baseline model byte before Q4 is scored/ranked.
Separate full-corpus guard: neither total nor body may regress>1% on any
reported split/preset. This does not erase the failed narrow regional guard
and cannot replace the listening decision that selected existing damping.
"""
import os,sys,json,shutil,hashlib,subprocess
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor

ROOT=Path(__file__).resolve().parents[2]
HERE=Path(__file__).parent
OUT=HERE/'full-corpus'
BASE=ROOT/'build-realism'/'cross-model-baseline'
FLAGS=['-std=c++20','-O3','-DNDEBUG','-arch','arm64','-mmacosx-version-min=11.0','-fPIC','-Wall','-Wextra','-Wpedantic']
ENV={**os.environ,'OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1'}
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def command(args,log):
    with Path(log).open('x') as f:
        result=subprocess.run([str(a) for a in args],stdout=f,stderr=subprocess.STDOUT,env=ENV,cwd=ROOT)
    if result.returncode:raise RuntimeError(f'failed {args}: see {log}')
    return {'command':[str(a) for a in args],'log':str(log),'log_sha256':sha(log)}
def parity(a,b):
    aa={p.name:p for p in Path(a).glob('model-*.f32')};bb={p.name:p for p in Path(b).glob('model-*.f32')}
    if aa.keys()!=bb.keys():raise RuntimeError(f'model file set differs {a} {b}')
    hashes=[]
    for name in sorted(aa):
        ha,hb=sha(aa[name]),sha(bb[name]);hashes.append({'file':name,'sha256':ha,'equal':ha==hb})
        if ha!=hb:raise RuntimeError(f'baseline audio parity failed {name}')
    return {'count':len(hashes),'models':hashes,'all_bit_identical':True}

def prepare():
    if OUT.exists():raise RuntimeError('full-corpus directory exists; preserve evidence and choose new version')
    OUT.mkdir()
    for q in (1,4):
        src=OUT/f'q{q}'/'Source';tools=OUT/f'q{q}'/'Tools';src.mkdir(parents=True);tools.mkdir()
        shutil.copytree(HERE/'frozen-dsp',src/'DSP')
        p=src/'DSP'/'AcustraEngine.cpp';s=p.read_text();needle='float offlineT1FrequencyScale=1.0f, offlineT1QScale=1.0f;';assert s.count(needle)==1
        p.write_text(s.replace(needle,f'float offlineT1FrequencyScale=1.0f, offlineT1QScale={q}.0f;'))
        for name in ('PhysicalFitRenderer.cpp','ExternalCorpusRenderer.cpp','BenchmarkOpenCorpora.py','OptimizePhysicalModel.py','FitPhysicalModel.py'):
            shutil.copyfile(ROOT/'Tools'/name,tools/name)
        shutil.copyfile(ROOT/'build-realism'/'next-current'/'libAcustraReferenceBank.a',OUT/f'q{q}'/'libAcustraReferenceBank.a')
    with ThreadPoolExecutor(max_workers=2) as pool:
        def build(q):
            p=OUT/f'q{q}';commands=[]
            commands.append(command(['c++',*FLAGS,'-I',p/'Source','-c',p/'Source/DSP/AcustraEngine.cpp','-o',p/'AcustraEngine.o'],p/'engine-build.log'))
            for tool in ('PhysicalFitRenderer','ExternalCorpusRenderer'):
                args=['c++',*FLAGS,'-I',p/'Source',p/'Tools'/f'{tool}.cpp',p/'AcustraEngine.o']
                if tool=='PhysicalFitRenderer':args.append(p/'libAcustraReferenceBank.a')
                args+=['-o',p/f'Acustra{tool}']
                commands.append(command(args,p/f'{tool}-build.log'))
            return commands
        builds=list(pool.map(build,(1,4)))
    return builds

def run_kind(q,model,kind,provenance):
    p=OUT/f'q{q}';dest=p/f'{kind}-{model}';src=provenance['runs'][model]
    if kind=='bank':
        cmd=list(src['bank_render']['command']);cmd[0]=str(p/'AcustraPhysicalFitRenderer')
        old=str(BASE/f'bank-{model}');assert old in cmd;cmd[cmd.index(old)]=str(dest)
        logs=[command(cmd,p/f'{model}-bank-render.log')]
        for split in ('train','validation','flattop'):
            logs.append(command([sys.executable,p/'Tools/FitPhysicalModel.py',dest/f'{split}.json'],dest/f'{split}-score.json'))
    else:
        cmd=list(src['external']['command']);cmd[0]=sys.executable;cmd[1]=str(p/'Tools/BenchmarkOpenCorpora.py')
        cmd[cmd.index('--renderer')+1]=str(p/'AcustraExternalCorpusRenderer');cmd[cmd.index('--output')+1]=str(dest)
        cmd[cmd.index('--jobs')+1]='1'
        logs=[command(cmd,p/f'{model}-external.log')]
    return {'q':q,'model':model,'kind':kind,'logs':logs,'output':str(dest)}

def scores(q,model):
    p=OUT/f'q{q}';reports=[]
    for kind in ('bank','external'):
        for path in sorted((p/f'{kind}-{model}').glob('*-score.json')):
            d=json.loads(path.read_text());reports.append({'kind':kind,'split':path.name.removesuffix('-score.json'),'examples':d['example_count'],'score':d['score'],
                'terms':d['terms'],'score_path':str(path),'score_sha256':sha(path)})
    return reports

def main():
    prov=json.loads((BASE/'provenance.json').read_text())
    builds=prepare();runs=[];checks=[]
    # Q1 runs are scored by the unchanged scorer, but never ranked until full
    # audio-byte parity versus root's current-preset baseline is proved.
    for q in (1,4):
        with ThreadPoolExecutor(max_workers=2) as pool:
            jobs=[(q,m,k,prov) for m in ('original','bellido1978') for k in ('bank','external')]
            result=list(pool.map(lambda args:run_kind(*args),jobs));runs+=result
        for model in ('original','bellido1978'):
            for kind in ('bank','external'):
                if q==1:checks.append({'q':q,'model':model,'kind':kind,**parity(OUT/'q1'/f'{kind}-{model}',BASE/f'{kind}-{model}')})
                elif model=='bellido1978':checks.append({'q':q,'model':model,'kind':kind,**parity(OUT/'q4'/f'{kind}-{model}',OUT/'q1'/f'{kind}-{model}')})
        (OUT/f'q{q}'/'completed-parity.json').write_text(json.dumps(checks,indent=2)+'\n')
        print(f'Q{q} full renders/scores and required audio parity complete',flush=True)
    comparisons=[]
    for model in ('original','bellido1978'):
        old=scores(1,model);new=scores(4,model)
        for r in new:
            b=next(s for s in old if s['kind']==r['kind'] and s['split']==r['split']);assert r['examples']==b['examples']
            changes={'total':100*(r['score']/b['score']-1)}
            changes.update({k:None if v['score'] is None else 100*(v['score']/b['terms'][k]['score']-1) for k,v in r['terms'].items()})
            comparisons.append({'model':model,'kind':r['kind'],'split':r['split'],'examples':r['examples'],
                'q1_score':b['score'],'q4_score':r['score'],'q1_terms':b['terms'],'q4_terms':r['terms'],'percent_change':changes,
                'full_corpus_total_body_guard_pass':changes['total']<=1 and changes['body']<=1})
    report={'schema':1,'candidate':'Original main/joint T1Q×4 with fixedfrequency, acoustic/reciprocalpole shared; namedBellido excluded.',
        'policy':{'full_corpus_guard':'No reported total or body regression>1% on any split/preset; all outcomes retained. Separate from failed narrow-region guard.',
                  'promotion':'Diagnostic only. Full descriptors do not override prior damping listening choice; listener review and native gates required.',
                  'preset_controls':prov['policy'],'flags':FLAGS,'unknown_picking':'Martin assumesFinger; perrowEastmanPick/Finger unchanged.'},
        'builds':builds,'runs':runs,'audio_parity':checks,'comparisons':comparisons,
        'all_total_body_guards_pass':all(r['full_corpus_total_body_guard_pass'] for r in comparisons),
        'sources':{'driver_sha256':sha(__file__),'baseline_provenance_sha256':sha(BASE/'provenance.json'),
                   'files':{str(p.relative_to(OUT)):sha(p) for p in sorted(OUT.rglob('*')) if p.is_file() and (p.suffix in ('.cpp','.h','.py') or p.name.startswith('Acustra') or p.name=='libAcustraReferenceBank.a')}}}
    (OUT/'summary.json').write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps({'all_total_body_guards_pass':report['all_total_body_guards_pass'],'comparisons':comparisons},indent=2))

if __name__=='__main__':main()

